 padding: 18px 38px;\n  border: 2px solid transparent;\n  text-transform: uppercase;\n  border-radius: 0px;\n  font-size: 14px;\n  line-height: 14px;\n  font-weight: 600;\n  box-shadow: rgb(153, 153, 153) 0px 0px 0px 0px;\n}\n.btn:focus {\n  outline: 0px;\n  border: 0px;\n  box-shadow: none;\n}\n\n.btn-main {\n  background: #f44336;\n  color: #fff;\n}\n.btn-main:hover {\n  color: #fff !important;\n  background: #000;\n}\n\n.btn-black {\n  background: #000;\n  color: #fff;\n}\n.btn-black:hover {\n  background: #f44336;\n  color: #fff;\n}\n\n.btn-white {\n  background: #fff;\n  color: #000;\n  border-color: #fff;\n}\n.btn-white:hover {\n  background: transparent;\n  color: #fff;\n}\n\na {\n  color: #000;\n  -webkit-transition: all 0.25s ease;\n  -moz-transition: all 0.25s ease;\n  -ms-transition: all 0.25s ease;\n  -o-transition: all 0.25s ease;\n  transition: all 0.25s ease;\n}\na:hover {\n  color: #f44336;\n  text-decoration: none;\n  outline: none;\n}\n\n.bg-primary {\n  background: #f44336 !important;\n}\n\n.bg-secondary {\n  background: #f7f7f7 !important;\n}\n\n.bg-extra {\n  background: #e8eefb !important;\n}\n\n.text-color {\n  color: #f44336;\n}\n\n.page-title h1 {\n  position: relative;\n  padding-bottom: 30px;\n}\n.page-title h1:after {\n  position: absolute;\n  content: \"\";\n  left: 50%;\n  bottom: 0px;\n  width: 40px;\n  height: 2px;\n  margin-left: -25px;\n  background: #f44336;\n}\n\n@media (max-width: 575px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n@media (max-width: 400px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n/* Typing hero */\n.cd-headline.clip span {\n  padding: 0;\n}\n\n.banner .cd-headline {\n  font-size: 56px;\n  line-height: 1.18;\n}\n\n.banner .cd-headline .cd-words-wrapper {\n  display: inline-block;\n  overflow: hidden;\n  vertical-align: top;\n}\n\n.banner-3 {\n  position: relative;\n}\n\n.banner {\n  position: relative;\n  overflow: hidden;\n  min-height: 650px;\n  display: fle